function countCombos(amount: number, coins: number[]): number {
  const go = (i: number, rest: number): number => {
    if (rest === 0) return 1;
    if (rest < 0 || i === coins.length) return 0;
    return go(i, rest - coins[i]) + go(i + 1, rest);
  };
  return go(0, amount);
}

