function countCombos(amount: number, coins: number[]): number {
  const n = coins.length;
  const dp: number[][] = Array.from({ length: n + 1 }, () => new Array(amount + 1).fill(0));
  dp[0][0] = 1;
  for (let i = 1; i <= n; i++) {
    const c = coins[i - 1];
    for (let x = 0; x <= amount; x++)
      dp[i][x] = dp[i - 1][x] + (x >= c ? dp[i][x - c] : 0);
  }
  return dp[n][amount];
}

