        dp = [[0] * (amount + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for i in range(1, n + 1):
            c = coins[i - 1]
            for x in range(amount + 1):
                dp[i][x] = dp[i - 1][x] + (dp[i][x - c] if x >= c else 0)
        return dp[n][amount]

