function countCombos(amount: number, coins: number[]): number {
  const ways = new Array(amount + 1).fill(0);
  ways[0] = 1;
  for (const c of coins)                 // coins outside: each combination counted once
    for (let x = c; x <= amount; x++)    // upward: this coin may repeat
      ways[x] += ways[x - c];
  return ways[amount];
}

